function isPalindrome(s) {
  const t = s.toLowerCase();
  let i = 0, j = t.length - 1;
  while (i < j) {
    if (t[i] !== t[j]) return false;
    i++;
    j--;
  }
  return true;
}

function compact(events) {
  const out = [];
  for (const e of events) {
    if (e == null || e.v === null || e.v === undefined) continue;
    const last = out[out.length - 1];
    if (last !== undefined && last.v === e.v) continue;
    out.push({ t: e.t, v: e.v });
  }
  return out;
}

function orderJobs(jobs) {
  if (!Array.isArray(jobs) || jobs.length === 0) return [];

  const known = new Set();
  for (const job of jobs) known.add(job.id);

  const indegree = new Map();
  const dependents = new Map();

  for (const job of jobs) {
    indegree.set(job.id, 0);
    dependents.set(job.id, []);
  }

  for (const job of jobs) {
    const seen = new Set();
    for (const dep of job.deps) {
      if (!known.has(dep)) return null;
      if (seen.has(dep)) continue; // duplicate dep entry counts once
      seen.add(dep);
      indegree.set(job.id, indegree.get(job.id) + 1);
      dependents.get(dep).push(job.id);
    }
  }

  // Min-heap on ids (lexicographic comparison)
  const heap = [];
  const less = (a, b) => String(a) < String(b);
  const push = (x) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!less(heap[i], heap[p])) break;
      [heap[i], heap[p]] = [heap[p], heap[i]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < heap.length && less(heap[l], heap[m])) m = l;
        if (r < heap.length && less(heap[r], heap[m])) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]];
        i = m;
      }
    }
    return top;
  };

  for (const job of jobs) {
    if (indegree.get(job.id) === 0) push(job.id);
  }

  const order = [];
  while (heap.length > 0) {
    const id = pop();
    order.push(id);
    for (const next of dependents.get(id)) {
      const left = indegree.get(next) - 1;
      indegree.set(next, left);
      if (left === 0) push(next);
    }
  }

  return order.length === jobs.length ? order : null;
}

function roundHalfEven(x, digits) {
  const f = Math.pow(10, digits);
  const y = x * f;
  const floor = Math.floor(y);
  const frac = y - floor;
  let r;
  if (frac > 0.5) r = floor + 1;
  else if (frac < 0.5) r = floor;
  else r = (floor % 2 === 0) ? floor : floor + 1;
  return r / f;
}
